/**
 * Recorded runs of the Python package (jev_rag) against the real Jev / Gemini APIs.
 * Generated by `python -m evaluation.export_replays` into public/replays.json.
 */

import { RunRecord, RunStatus } from '../domain/trace';

export interface ReplayMeta {
  jevModel: string;
  generationModel: string;
  embeddingModel: string;
  thresholds: RunRecord['thresholds'];
  note: string;
}

export interface ReplayRecord {
  id: string;
  split: 'test' | 'dev';
  type: string;
  query: string;
  answerable: boolean;
  status: RunStatus;
  answer: string;
  triage: {
    intent: string;
    intent_confidence: number;
    route: string | null;
    route_confidence: number;
    decompose: number;
  };
  subQueries: string[];
  retrieved: { id: string; title: string; heading: string; text: string; relevance: number | null; accepted: boolean }[];
  sufficiency: number | null;
  claims: { text: string; support: number | null; supported: boolean | null }[];
  timingsMs: RunRecord['timingsMs'];
  totalMs: number | null;
  jevCalls: number;
  llmTokens: number;
  baseline: { answer: string; totalMs: number | null; llmTokens: number };
}

export interface ReplayData {
  meta: ReplayMeta;
  records: ReplayRecord[];
}

export async function loadReplays(url = `${import.meta.env.BASE_URL}replays.json`): Promise<ReplayData> {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`failed to load ${url}: ${res.status}`);
  return (await res.json()) as ReplayData;
}

export function runFromReplay(r: ReplayRecord, meta: ReplayMeta): RunRecord {
  return {
    query: r.query,
    status: r.status,
    answer: r.answer,
    triage: {
      intent: r.triage.intent,
      intentConfidence: r.triage.intent_confidence,
      route: r.triage.route,
      routeConfidence: r.triage.route_confidence,
      decompose: r.triage.decompose,
    },
    subQueries: r.subQueries,
    retrieved: r.retrieved,
    sufficiency: r.sufficiency,
    claims: r.claims,
    timingsMs: r.timingsMs,
    totalMs: r.totalMs,
    jevCalls: r.jevCalls,
    llmTokens: r.llmTokens,
    thresholds: meta.thresholds,
    baseline: r.baseline,
  };
}
